1	import { useState } from 'react';
2	
3	import { events, selectDesktopAnalyticsDep } from '@suite/analytics';
4	import { LearnMoreButton } from '@suite/external-links';
5	import { Translation } from '@suite/intl';
6	import { isAdditionalShamirBackupInProgress } from '@suite/recovery';
7	import { useServices } from '@suite-common/dependency-injection';
8	import { selectSelectedDevice } from '@suite-common/device';
9	import { Modal, type ModalProps } from '@trezor/components';
10	import TrezorConnect, { PROTO } from '@trezor/connect';
11	import { ConfirmOnDevicePill } from '@trezor/product-components';
12	import {
13	    HELP_CENTER_KEEPING_SEED_SAFE_URL,
14	    HELP_CENTER_UPGRADING_TO_MULTI_SHARE_URL,
15	    TREZOR_SUPPORT_RECOVERY_ISSUES_URL,
16	} from '@trezor/urls';
17	
18	import { useSelector } from 'src/hooks/suite';
19	
20	import { MultiShareBackupStep1 } from './MultiShareBackupStep1';
21	import { MultiShareBackupStep2to4 } from './MultiShareBackupStep2to4';
22	import { MultiShareBackupStep5 } from './MultiShareBackupStep5';
23	import { type Steps, steps } from './steps';
24	
25	type MultiShareBackupModalProps = {
26	    onCancel: () => void;
27	};
28	
29	type StepConfig = Partial<ModalProps>;
30	
31	export const MultiShareBackupModal = ({ onCancel }: MultiShareBackupModalProps) => {
32	    const { analytics } = useServices(selectDesktopAnalyticsDep);
33	    const device = useSelector(selectSelectedDevice);
34	
35	    const isInBackupMode =
36	        device?.features !== undefined && isAdditionalShamirBackupInProgress(device.features);
37	
38	    const [step, setStep] = useState<Steps>(isInBackupMode ? 'backup-seed' : 'first-info');
39	
40	    const [isChecked1, setIsChecked1] = useState(false);
41	    const [isChecked2, setIsChecked2] = useState(false);
42	
43	    const learnMoreClicked = () => {
44	        analytics.report({
45	            type: events.settingsDeviceMultiShareBackupEvent.name,
46	            payload: { action: 'learn-more' },
47	        });
48	    };
49	
50	    const handleCancel = () => {
51	        if (step !== 'done') {
52	            analytics.report({
53	                type: events.settingsDeviceMultiShareBackupEvent.name,
54	                payload: { action: 'close-modal' },
55	            });
56	        }
57	
58	        onCancel();
59	    };
60	
61	    const closeWithCancelOnDevice = () => {
62	        TrezorConnect.cancel({ reason: 'cancel' });
63	        handleCancel();
64	    };
65	
66	    if (device === undefined) {
67	        return;
68	    }
69	
70	    const getStepConfig = (): StepConfig => {
71	        switch (step) {
72	            case 'first-info': {
73	                const goToStepNextStep = () => setStep('second-info');
74	
75	                return {
76	                    width: 600,
77	                    children: (
78	                        <MultiShareBackupStep1
79	                            isChecked1={isChecked1}
80	                            isChecked2={isChecked2}
81	                            setIsChecked1={setIsChecked1}
82	                            setIsChecked2={setIsChecked2}
83	                        />
84	                    ),
85	                    bottomContent: (
86	                        <>
87	                            <Modal.Button
88	                                onClick={goToStepNextStep}
89	                                data-testid="@multi-share-backup/1st-info/submit-button"
90	                                isDisabled={!isChecked1 || !isChecked2}
91	                            >
92	                                <Translation id="TR_CREATE_MULTI_SHARE_BACKUP" />
93	                            </Modal.Button>
94	                            <LearnMoreButton
95	                                url={HELP_CENTER_UPGRADING_TO_MULTI_SHARE_URL}
96	                                size="large"
97	                                onClick={learnMoreClicked}
98	                            />
99	                        </>
100	                    ),
101	                };
102	            }
103	
104	            case 'second-info': {
105	                const enterBackup = async () => {
106	                    setStep('verify-ownership');
107	
108	                    const response = await TrezorConnect.recoveryDevice({
109	                        type: 'UnlockRepeatedBackup',
110	                        input_method: PROTO.RecoveryDeviceInputMethod.Matrix,
111	                        enforce_wordlist: true,
112	                        device: {
113	                            path: device.path,
114	                        },
115	                    });
116	
117	                    if (response.success) {
118	                        setStep('backup-seed');
119	                        TrezorConnect.backupDevice({
120	                            device: {
121	                                path: device.path,
122	                            },
123	                        }).then(response => {
124	                            if (response.success) {
125	                                analytics.report({
126	                                    type: events.settingsDeviceMultiShareBackupEvent.name,
127	                                    payload: { action: 'done' },
128	                                });
129	
130	                                setStep('done');
131	                            } else {
132	                                handleCancel();
133	                            }
134	                        });
135	                    } else {
136	                        handleCancel();
137	                    }
138	                };
139	
140	                return {
141	                    children: <MultiShareBackupStep2to4 step={step} />,
142	                    bottomContent: (
143	                        <>
144	                            <Modal.Button
145	                                onClick={enterBackup}
146	                                data-testid="@multi-share-backup/2nd-info/submit-button"
147	                            >
148	                                <Translation id="TR_ENTER_EXISTING_BACKUP" />
149	                            </Modal.Button>
150	                            <LearnMoreButton url={TREZOR_SUPPORT_RECOVERY_ISSUES_URL} size="large">
151	                                <Translation id="TR_DONT_HAVE_BACKUP" />
152	                            </LearnMoreButton>
153	                        </>
154	                    ),
155	                    onBackClick: () => setStep('first-info'),
156	                };
157	            }
158	
159	            case 'verify-ownership':
160	                return {
161	                    children: <MultiShareBackupStep2to4 step={step} />,
162	                    // There is a bug in FW, that prevents cancel during recovery-check
163	                    // https://github.com/trezor/trezor-firmware/issues/3503
164	                    onCancel: undefined,
165	                };
166	
167	            case 'backup-seed':
168	                return {
169	                    children: <MultiShareBackupStep2to4 step={step} />,
170	                    onCancel: closeWithCancelOnDevice,
171	                };
172	
173	            case 'done':
174	                return {
175	                    heading: <Translation id="TR_CREATE_MULTI_SHARE_BACKUP_CREATED" />,
176	                    children: <MultiShareBackupStep5 />,
177	                    bottomContent: (
178	                        <>
179	                            <Modal.Button
180	                                onClick={handleCancel}
181	                                data-testid="@multi-share-backup/done/got-it-button"
182	                            >
183	                                <Translation id="TR_GOT_IT_BUTTON" />
184	                            </Modal.Button>
185	                            <LearnMoreButton url={HELP_CENTER_KEEPING_SEED_SAFE_URL} size="medium">
186	                                <Translation id="TR_MULTI_SHARE_TIPS_ON_STORING_BACKUP" />
187	                            </LearnMoreButton>
188	                        </>
189	                    ),
190	                };
191	        }
192	    };
193	
194	    const isDeviceStep = ['verify-ownership', 'backup-seed'].includes(step);
195	
196	    return (
197	        <Modal.Backdrop onClick={isDeviceStep ? undefined : handleCancel}>
198	            {isDeviceStep && (
199	                <ConfirmOnDevicePill
200	                    title={<Translation id="TR_CONFIRM_ON_TREZOR" />}
201	                    deviceModelInternal={device.features?.internal_model}
202	                    deviceUnitColor={device?.features?.unit_color}
203	                />
204	            )}
205	            <Modal.ModalBase
206	                onCancel={handleCancel}
207	                heading={<Translation id="TR_CREATE_MULTI_SHARE_BACKUP" />}
208	                description={
209	                    <Translation
210	                        id="TR_STEP_OF_TOTAL"
211	                        values={{
212	                            index: steps.indexOf(step) + 1,
213	                            total: steps.length,
214	                        }}
215	                    />
216	                }
217	                {...getStepConfig()}
218	            />
219	        </Modal.Backdrop>
220	    );
221	};
