79	
80	export const MultiShareBackupStep2to4 = ({ step }: MultiShareBackupStep2to4Props) => (
81	    <StepList isOrdered margin={{ top: 16 }}>
82	        <Step
83	            time={2}
84	            title="TR_VERIFY_TREZOR_OWNERSHIP"
85	            state={step === 'backup-seed' ? 'done' : 'default'}
86	        >
87	            <Paragraph intent="neutral" priority="secondary">
88	                <Translation id="TR_VERIFY_TREZOR_OWNERSHIP_EXPLANATION" />
89	            </Paragraph>
90	            <Grid margin={{ top: 16 }} columns={2} gap={12}>
91	                <InstructionItem icon={RecoverySeedIcon}>
92	                    <Translation id="TR_VERIFY_TREZOR_OWNERSHIP_CARD_1" />
93	                </InstructionItem>
94	                <InstructionItem icon={CameraSlashIcon}>
95	                    <Translation id="TR_VERIFY_TREZOR_OWNERSHIP_CARD_2" />
96	                </InstructionItem>
97	            </Grid>
98	        </Step>
99	        <Step
100	            time={10}
101	            title="TR_CREATE_SHARES"
102	            state={step === 'verify-ownership' ? 'pending' : 'default'}
103	        >
104	            <Paragraph intent="neutral" priority="secondary">
105	                <Translation id="TR_CREATE_SHARES_EXPLANATION" />{' '}
106	                <Translation id="TR_CREATE_SHARES_EXAMPLE" />
107	            </Paragraph>
108	            <Grid margin={{ top: 20 }} columns={3} gap={12}>
109	                <InstructionItem direction="column" icon={PencilIcon}>
110	                    <Translation
111	                        id="TR_CREATE_SHARES_CARD_1"
112	                        values={{
113	                            cardsLink: chunks => (
114	                                <TrezorLink href={HELP_CENTER_SEED_CARD_URL}>{chunks}</TrezorLink>
115	                            ),
116	                            keepLink: chunks => (
117	                                <TrezorLink href={ESHOP_KEEP_METAL_MULTI_SHARE_URL}>
118	                                    {chunks}
119	                                </TrezorLink>
120	                            ),
121	                        }}
122	                    />
123	                </InstructionItem>
124	                <InstructionItem direction="column" icon={CameraSlashIcon}>
125	                    <Translation id="TR_CREATE_SHARES_CARD_2" />
126	                </InstructionItem>
127	                <InstructionItem direction="column" icon={EyeSlashIcon}>
128	                    <Translation id="TR_CREATE_SHARES_CARD_3" />
129	                </InstructionItem>
130	            </Grid>
131	        </Step>
132	    </StepList>
133	);
