1	import { type PayloadAction, createSlice } from '@reduxjs/toolkit';
2	
3	import type { ConfirmKey } from './types';
4	
5	export const actionPrefix = '@suite/backup';
6	
7	export interface BackupState {
8	    userConfirmed: ConfirmKey[];
9	    inProgress: boolean;
10	    error?: string;
11	}
12	
13	const initialState: BackupState = {
14	    userConfirmed: [],
15	    inProgress: false,
16	};
17	
18	export const backupSlice = createSlice({
19	    name: 'backup',
20	    initialState,
21	    reducers: {
22	        toggleCheckboxByKey: (state, { payload }: PayloadAction<ConfirmKey>) => {
23	            if (!state.userConfirmed.includes(payload)) {
24	                state.userConfirmed.push(payload);
25	
26	                return;
27	            }
28	            state.userConfirmed.splice(
29	                state.userConfirmed.findIndex(r => r === payload),
30	                1,
31	            );
32	        },
33	        setInProgress: (state, { payload }: PayloadAction<boolean>) => {
34	            state.inProgress = payload;
35	        },
36	        setError: (state, { payload }: PayloadAction<string>) => {
37	            state.inProgress = false;
38	            state.error = payload;
39	        },
40	        resetReducer: () => initialState,
41	    },
42	});
43	
44	export const backupActions = backupSlice.actions;
45	export const backupReducer = backupSlice.reducer;
