1	import { useState } from 'react';
2	import { useDispatch, useSelector } from 'react-redux';
3	
4	import { LearnMoreButton } from '@suite/external-links';
5	import { Translation } from '@suite/intl';
6	import {
7	    AdditionalBackupDisclaimer,
8	    AdditionalBackupSteps,
9	    AdditionalBackupSuccess,
10	} from '@suite/nfc';
11	import { isAdditionalShamirBackupInProgress } from '@suite/recovery';
12	import { selectIsN4w1BackupEnabled } from '@suite/settings';
13	import { selectSelectedDevice } from '@suite-common/device';
14	import { notificationsActions } from '@suite-common/toast-notifications';
15	import { Modal } from '@trezor/components';
16	import TrezorConnect, { PROTO } from '@trezor/connect';
17	import { ConfirmOnDevicePill } from '@trezor/product-components';
18	import { exhaustive } from '@trezor/type-utils';
19	import { HELP_CENTER_MULTI_SHARE_BACKUP_URL } from '@trezor/urls';
20	
21	type CreateWalletBackupModalProps = {
22	    onCancel: () => void;
23	};
24	
25	type Step = 'disclaimer' | 'how-it-works' | 'verify-ownership' | 'backup' | 'done';
26	
27	export const CreateWalletBackupModal = ({ onCancel }: CreateWalletBackupModalProps) => {
28	    const device = useSelector(selectSelectedDevice);
29	    const dispatch = useDispatch();
30	    const isN4w1BackupEnabled = useSelector(selectIsN4w1BackupEnabled);
31	
32	    const backupMethod = isN4w1BackupEnabled ? PROTO.BackupMethod.N4W1 : PROTO.BackupMethod.Display;
33	
34	    const isInBackupMode =
35	        device?.features !== undefined && isAdditionalShamirBackupInProgress(device.features);
36	
37	    const [step, setStep] = useState<Step>(isInBackupMode ? 'backup' : 'disclaimer');
38	    const [isChecked, setIsChecked] = useState(false);
39	
40	    if (device === undefined) {
41	        return null;
42	    }
43	
44	    const closeWithCancelOnDevice = () => {
45	        TrezorConnect.cancel('cancel');
46	        onCancel();
47	    };
48	
49	    const startBackupFlow = async () => {
50	        setStep('verify-ownership');
51	
52	        const verifyResult = await TrezorConnect.recoveryDevice({
53	            type: 'UnlockRepeatedBackup',
54	            input_method: PROTO.RecoveryDeviceInputMethod.Matrix,
55	            enforce_wordlist: true,
56	            device: { path: device.path },
57	        });
58	
59	        if (!verifyResult.success) {
60	            dispatch(notificationsActions.addToast({ type: 'backup-failed' }));
61	            onCancel();
62	
63	            return;
64	        }
65	
66	        setStep('backup');
67	
68	        const backupResult = await TrezorConnect.backupDevice({
69	            backup_method: backupMethod,
70	            device: { path: device.path },
71	        });
72	
73	        if (!backupResult.success) {
74	            dispatch(notificationsActions.addToast({ type: 'backup-failed' }));
75	            onCancel();
76	
77	            return;
78	        }
79	
80	        setStep('done');
81	    };
82	
83	    const isDeviceStep = step === 'verify-ownership' || step === 'backup';
84	
85	    const getContent = () => {
86	        switch (step) {
87	            case 'disclaimer':
88	                return {
89	                    heading: <Translation id="TR_CREATE_ADDITIONAL_BACKUP" />,
90	                    onCancel,
91	                    children: (
92	                        <AdditionalBackupDisclaimer
93	                            isChecked={isChecked}
94	                            setIsChecked={setIsChecked}
95	                        />
96	                    ),
97	                    bottomContent: (
98	                        <>
99	                            <Modal.Button
100	                                onClick={() => setStep('how-it-works')}
101	                                isDisabled={!isChecked}
102	                                data-testid="@additional-backup/disclaimer/continue-button"
103	                            >
104	                                <Translation id="TR_CONTINUE" />
105	                            </Modal.Button>
106	                            <LearnMoreButton
107	                                url={HELP_CENTER_MULTI_SHARE_BACKUP_URL}
108	                                size="large"
109	                            />
110	                        </>
111	                    ),
112	                };
113	
114	            case 'how-it-works':
115	                return {
116	                    heading: <Translation id="TR_CREATE_ADDITIONAL_BACKUP" />,
117	                    onCancel,
118	                    description: (
119	                        <Translation id="TR_STEP_OF_TOTAL" values={{ index: 1, total: 2 }} />
120	                    ),
121	                    children: <AdditionalBackupSteps step="verify-ownership" />,
122	                    bottomContent: (
123	                        <>
124	                            <Modal.Button
125	                                onClick={startBackupFlow}
126	                                data-testid="@additional-backup/enter-backup-button"
127	                            >
128	                                <Translation id="TR_ENTER_EXISTING_BACKUP" />
129	                            </Modal.Button>
130	                            <LearnMoreButton url={HELP_CENTER_MULTI_SHARE_BACKUP_URL} size="large">
131	                                <Translation id="TR_DONT_HAVE_BACKUP" />
132	                            </LearnMoreButton>
133	                        </>
134	                    ),
135	                };
136	
137	            case 'verify-ownership':
138	                return {
139	                    heading: <Translation id="TR_CREATE_ADDITIONAL_BACKUP" />,
140	                    onCancel: undefined,
141	                    description: (
142	                        <Translation id="TR_STEP_OF_TOTAL" values={{ index: 1, total: 2 }} />
143	                    ),
144	                    children: <AdditionalBackupSteps step="verify-ownership" />,
145	                };
146	
147	            case 'backup':
148	                return {
149	                    heading: <Translation id="TR_CREATE_ADDITIONAL_BACKUP" />,
150	                    onCancel: closeWithCancelOnDevice,
151	                    description: (
152	                        <Translation id="TR_STEP_OF_TOTAL" values={{ index: 2, total: 2 }} />
153	                    ),
154	                    children: <AdditionalBackupSteps step="backup" />,
155	                };
156	
157	            case 'done':
158	                return {
159	                    heading: undefined,
160	                    onCancel,
161	                    children: <AdditionalBackupSuccess />,
162	                    bottomContent: (
163	                        <Modal.Button
164	                            onClick={onCancel}
165	                            data-testid="@additional-backup/done/got-it-button"
166	                        >
167	                            <Translation id="TR_GOT_IT_BUTTON" />
168	                        </Modal.Button>
169	                    ),
170	                };
171	            default:
172	                return exhaustive(step);
173	        }
174	    };
175	
176	    return (
177	        <Modal.Backdrop onClick={isDeviceStep ? undefined : onCancel}>
