29	export const Backup = ({
30	    onCancel,
31	}: ForegroundAppProps): NonNullable<ReactNode> /* NonNullable return type is required here to prevent default return from switch-case */ => {
32	    const device = useSelector(selectSelectedDevice);
33	    const backup = useSelector(selectBackup);
34	    const backupStatus = useSelector(selectBackupStatus);
35	
36	    const isDeviceUnavailable = !isDeviceAcquired(device) || !device.connected;
37	
38	    if (isDeviceUnavailable) {
39	        return (
40	            <Modal
41	                heading={<Translation id="TR_RECONNECT_HEADER" />}
42	                onCancel={onCancel}
43	                data-testid="@backup/no-device"
44	            >
45	                <Column alignItems="center">
46	                    <Image image="CONNECT_DEVICE" width="360" />
47	                </Column>
48	            </Modal>
49	        );
50	    }
51	
52	    /*
53	        Edge case, user disconnected the device he was doing backup initially with and connected another device
54	        with backup finished or failed. Either way, there is no way.
55	    */
56	    if (
57	        backupStatus !== 'finished' &&
58	        !backup.error &&
59	        device.features.backup_availability !== 'Required' &&
60	        device.features.unfinished_backup !== null
61	    ) {
62	        return (
63	            <Modal
64	                onCancel={onCancel}
65	                heading={getEdgeCaseModalHeading(device.features.unfinished_backup)}
66	                icon={device.features.unfinished_backup ? WarningIcon : CheckIcon}
67	                intent={device.features.unfinished_backup ? 'warning' : 'brand'}
68	                bottomContent={
69	                    <Modal.Button onClick={() => onCancel()} data-testid="@backup/close-button">
70	                        <Translation id="TR_CLOSE" />
71	                    </Modal.Button>
72	                }
73	            >
74	                {device.features.unfinished_backup ? (
75	                    <Text
76	                        intent="neutral"
77	                        priority="secondary"
78	                        data-testid="@backup/already-failed-message"
79	                    >
80	                        <Translation id="BACKUP_BACKUP_ALREADY_FAILED_DESCRIPTION" />
81	                        <TrezorLink href={HELP_CENTER_RECOVERY_ISSUES_URL}>
82	                            <Translation id="TR_LEARN_MORE" />
83	                        </TrezorLink>
84	                    </Text>
85	                ) : (
86	                    <Text
87	                        intent="neutral"
88	                        priority="secondary"
89	                        data-testid="@backup/already-finished-message"
90	                    >
91	                        <Translation id="BACKUP_BACKUP_ALREADY_FINISHED_DESCRIPTION" />
92	                    </Text>
93	                )}
94	            </Modal>
95	        );
96	    }
97	
98	    switch (backupStatus) {
99	        case 'initial':
100	            return <BackupStep1Initial onCancel={onCancel} backup={backup} />;
101	        case 'in-progress':
102	            return <BackupStep2InProgress onCancel={onCancel} />;
103	        case 'finished':
104	            return <BackupStep3Finished onCancel={onCancel} backup={backup} />;
105	        case 'error':
